class Solution:
    def canMakePaliQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        res = []
        for l, r, k in queries:
            cnt = [0] * 26
            for i in range(l, r + 1):
                cnt[ord(s[i]) - 97] += 1
            odd = sum(c & 1 for c in cnt)
            res.append(odd // 2 <= k)
        return res

