class Solution:
    def canMakePaliQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        pre = [0] * (n + 1)
        for i, ch in enumerate(s):
            pre[i + 1] = pre[i] ^ (1 << (ord(ch) - 97))
        return [(pre[r + 1] ^ pre[l]).bit_count() // 2 <= k
                for l, r, k in queries]

