class Solution {
public:
    vector<bool> canMakePaliQueries(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<int> pre(n + 1, 0);
        for (int i = 0; i < n; i++)
            pre[i + 1] = pre[i] ^ (1 << (s[i] - 'a'));
        vector<bool> res;
        res.reserve(queries.size());
        for (auto& q : queries) {
            int odd = __builtin_popcount(pre[q[1] + 1] ^ pre[q[0]]);
            res.push_back(odd / 2 <= q[2]);
        }
        return res;
    }
};

