var canMakePaliQueries = function(s, queries) {
    const n = s.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++)
        pre[i + 1] = pre[i] ^ (1 << (s.charCodeAt(i) - 97));
    return queries.map(([l, r, k]) => {
        let m = pre[r + 1] ^ pre[l], odd = 0;
        while (m) { m &= m - 1; odd++; }
        return Math.floor(odd / 2) <= k;
    });
};
